	return out
}

// Shadowed returns the nodes that are not lit, in docket order.
func (a *Analysis) Shadowed() []*shadow.Node {
	var out []*shadow.Node
	for _, n := range a.Nodes {
		if n.Shadowed() {
			out = append(out, n)
		}
	}
	return out
}

