#!/usr/bin/env python3
"""Finding A, measured from a graph snapshot alone.

Query, stated so it can be rerun by hand:

  entire graph snapshot --repo <repo> --format ndjson > snap.ndjson

  symbols   = {r["id"]: r for r in snap if r["record_type"] == "symbol"}
  externals = {r["id"]    for r in snap if r["record_type"] == "external"}

  For every r with r["record_type"] == "relation" and r["type"] == "CALLS":
      origin = symbols.get(r["from_id"])            # skip file-level edges
      bucket = "test" if origin.file_path startswith TESTDIR else "source"
      dest   = "same-repo" if r["to_id"] in symbols else
               "external"  if r["to_id"] in externals else "unresolved-id"

Counts are of CALLS edges, which is what the click number counted.
"""
import json, sys

def load(path):
    syms, ext, rels = {}, set(), []
    for line in open(path):
        line = line.strip()
        if not line:
            continue
        try:
            r = json.loads(line)
        except ValueError:
            continue
        t = r.get("record_type")
        if t == "symbol":
            syms[r["id"]] = r
        elif t == "external":
            ext.add(r["id"])
        elif t == "relation":
            rels.append(r)
    return syms, ext, rels

def measure(path, testdir, kinds=("CALLS",)):
    syms, ext, rels = load(path)
    out = {}
    for r in rels:
        if r.get("type") not in kinds:
            continue
        origin = syms.get(r.get("from_id"))
        if origin is None:
            continue                      # file-level DEFINES/IMPORTS edges
        bucket = "test" if origin["file_path"].startswith(testdir) else "source"
        to = r.get("to_id")
        if to in syms:
            dest = "same-repo"
        elif to in ext:
            dest = "external"
        else:
            dest = "unresolved-id"
        out[(bucket, dest)] = out.get((bucket, dest), 0) + 1
    return out

if __name__ == "__main__":
    rows = [("click", "/tmp/claude-1000/snaps/click.ndjson", "tests/"),
            ("httpx", "/tmp/claude-1000/snaps/httpx.ndjson", "tests/"),
            ("pre-commit", "/tmp/claude-1000/snaps/pre-commit.ndjson", "tests/")]
    print(f"{'repo':12} {'origin':8} {'same-repo':>10} {'external':>10} {'other':>7} {'total':>7} {'external %':>11}")
    for name, path, td in rows:
        m = measure(path, td)
        for bucket in ("test", "source"):
            same = m.get((bucket, "same-repo"), 0)
            extn = m.get((bucket, "external"), 0)
            oth  = m.get((bucket, "unresolved-id"), 0)
            tot  = same + extn + oth
            pct  = (100.0 * extn / tot) if tot else 0.0
            print(f"{name:12} {bucket:8} {same:10} {extn:10} {oth:7} {tot:7} {pct:10.1f}%")
        print()
